let lang = (() => {
  try { const s = localStorage.getItem("dsp_lang"); if (s === "ru" || s === "en" || s === "kk") return s; } catch { /* нет хранилища — берём язык устройства */ }
  // первый запуск: язык устройства или браузера (список предпочтений, а не регион)
  for (const l of navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || "en"]) {
    const p = String(l).toLowerCase().split("-")[0];
    if (p === "ru" || p === "kk") return p;
    if (p === "en") return "en";
  }
  return "en";
})();

try { document.documentElement.lang = lang; } catch { /* нет документа */ }
export const getLang = () => lang;
export function setLang(l) { lang = l; try { localStorage.setItem("dsp_lang", l); } catch { /* ignore */ } document.documentElement.lang = l; }
export function t(key, vars) {
  let s = (DICT[lang] && DICT[lang][key]) || DICT.en[key] || key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}
